-- =====================================================================
-- Salinan backup yang BISA DIBACA (CSV), dipanggil oleh tools\backup.ps1 (D-49).
-- HANYA MEMBACA (select). Tidak membuat/mengubah apa pun di database; fungsi bantu dibuat di pg_temp (hilang sendiri).
-- __DIR__ diganti otomatis oleh backup.ps1 dengan folder tujuan.
-- Tidak ikut: hash PIN, token sesi, catatan percobaan login (rahasia; tetap ada di file .dump).
-- Teks yang diawali = + - @ diberi tanda ' di depan (sama seperti Export Excel aplikasi; aman dibuka di Excel).
-- =====================================================================
\set ON_ERROR_STOP on
set client_encoding = 'UTF8';

create function pg_temp.t(x text) returns text language sql immutable as $$
  select case when x ~ '^[=+@\t\r-]' then '''' || x else x end
$$;
create function pg_temp.wib(x timestamptz) returns text language sql immutable as $$
  select to_char(x at time zone 'Asia/Jakarta', 'YYYY-MM-DD HH24:MI')
$$;
create function pg_temp.bulan(m int) returns text language sql immutable as $$
  select (array['Januari','Februari','Maret','April','Mei','Juni','Juli','Agustus','September','Oktober','November','Desember'])[m]
$$;
-- Mulai di sini semua transaksi hanya-baca: data aplikasi tidak mungkin berubah
set default_transaction_read_only = on;

\copy (with t as (select p.id, p.division_id, p.status, coalesce((select sum(i.subtotal) from public.program_items i where i.program_id = p.id), 0) total from public.programs p), r as (select g.sort_order gs, d.sort_order ds, g.name grup, d.name divisi, count(t.id) filter (where t.status = 'diajukan') n_diajukan, count(t.id) filter (where t.status = 'draft') n_draft, coalesce(sum(t.total) filter (where t.status = 'diajukan'), 0) tot_diajukan, coalesce(sum(t.total) filter (where t.status = 'draft'), 0) tot_draft from public.divisions d join public.division_groups g on g.id = d.group_id left join t on t.division_id = d.id group by g.sort_order, d.sort_order, g.name, d.name) select pg_temp.t(grup) as "Grup", pg_temp.t(divisi) as "Divisi", n_diajukan as "Program Diajukan", n_draft as "Draft", tot_diajukan as "Total Diajukan (Rp)", tot_draft as "Total Draft (Rp)" from (select 0 k, gs, ds, grup, divisi, n_diajukan, n_draft, tot_diajukan, tot_draft from r union all select 1, 0, 0, 'TOTAL', '', sum(n_diajukan), sum(n_draft), sum(tot_diajukan), sum(tot_draft) from r) x order by k, gs, ds, divisi) to '__DIR__/1_ringkasan_divisi.csv' with (format csv, header true, encoding 'UTF8')

\copy (select pg_temp.t(d.name) as "Divisi", pg_temp.t(g.name) as "Grup", pg_temp.t(p.nama_program) as "Nama Program", pg_temp.t(pc.name) as "Kategori Program", pg_temp.bulan(p.periode_bulan) as "Bulan", p.periode_bulan as "Bulan (angka)", pg_temp.t(p.pic_nama) as "PIC", case p.status when 'diajukan' then 'Diajukan' else 'Draft' end as "Status", p.tanggal_pengajuan as "Tanggal Pengajuan", (select count(*) from public.program_items i where i.program_id = p.id) as "Jumlah Baris", coalesce((select sum(i.subtotal) from public.program_items i where i.program_id = p.id), 0) as "Total (Rp)", case when exists (select 1 from public.program_item_history h where h.program_id = p.id and h.actor_role = 'finance') then 'Ya' else '' end as "Direvisi Finance", pg_temp.wib(p.created_at) as "Dibuat (WIB)", pg_temp.wib(p.updated_at) as "Terakhir Diubah (WIB)", pg_temp.t(p.updated_by_name) as "Diubah Oleh", p.id as "ID Program" from public.programs p join public.divisions d on d.id = p.division_id join public.division_groups g on g.id = d.group_id join public.program_categories pc on pc.id = p.program_category_id order by g.sort_order, d.sort_order, p.periode_bulan, lower(p.nama_program), p.id) to '__DIR__/2_program.csv' with (format csv, header true, encoding 'UTF8')

\copy (select pg_temp.t(d.name) as "Divisi", pg_temp.t(g.name) as "Grup", pg_temp.t(p.nama_program) as "Nama Program", case p.status when 'diajukan' then 'Diajukan' else 'Draft' end as "Status", pg_temp.bulan(p.periode_bulan) as "Bulan", i.urutan as "No", pg_temp.t(i.uraian) as "Uraian", pg_temp.t(ic.name) as "Kategori Kebutuhan", i.qty as "Qty", pg_temp.t(i.satuan) as "Satuan", i.harga_satuan as "Harga Satuan (Rp)", i.subtotal as "Subtotal (Rp)", pg_temp.t(i.catatan) as "Catatan", p.id as "ID Program", i.id as "ID Baris" from public.program_items i join public.programs p on p.id = i.program_id join public.divisions d on d.id = p.division_id join public.division_groups g on g.id = d.group_id left join public.item_categories ic on ic.id = i.item_category_id order by g.sort_order, d.sort_order, p.periode_bulan, lower(p.nama_program), p.id, i.urutan) to '__DIR__/3_rincian_kebutuhan.csv' with (format csv, header true, encoding 'UTF8')

\copy (select pg_temp.wib(h.occurred_at) as "Waktu (WIB)", pg_temp.t(d.name) as "Divisi", pg_temp.t(coalesce(p.nama_program, '(program sudah dihapus)')) as "Nama Program", case h.actor_role when 'finance' then 'Finance' else pg_temp.t(d.name) end as "Oleh", case h.change_type when 'tambah' then 'Ditambahkan' when 'ubah' then 'Diubah' when 'hapus' then 'Dihapus' else h.change_type end as "Perubahan", pg_temp.t(h.old_data ->> 'uraian') as "Uraian Sebelum", pg_temp.t(h.new_data ->> 'uraian') as "Uraian Sesudah", (h.old_data ->> 'subtotal') as "Subtotal Sebelum (Rp)", (h.new_data ->> 'subtotal') as "Subtotal Sesudah (Rp)", pg_temp.t(h.reason) as "Alasan", h.old_data::text as "Data Sebelum (teknis)", h.new_data::text as "Data Sesudah (teknis)", h.program_id as "ID Program", h.item_id as "ID Baris" from public.program_item_history h join public.divisions d on d.id = h.division_id left join public.programs p on p.id = h.program_id order by h.occurred_at, h.id) to '__DIR__/4_riwayat_revisi_item.csv' with (format csv, header true, encoding 'UTF8')

\copy (select pg_temp.wib(a.occurred_at) as "Waktu (WIB)", case a.actor_role when 'finance' then 'Finance' when 'division' then 'Divisi' else 'Sistem' end as "Peran", pg_temp.t(d.name) as "Divisi", pg_temp.t(a.actor_name) as "Nama", a.action as "Aksi", a.entity_type as "Objek", pg_temp.t(coalesce(a.new_data ->> 'nama_program', a.old_data ->> 'nama_program')) as "Nama Program", pg_temp.t(a.reason) as "Alasan", a.old_data::text as "Data Sebelum (teknis)", a.new_data::text as "Data Sesudah (teknis)", a.entity_id as "ID Objek" from public.audit_log a left join public.divisions d on d.id = a.division_id order by a.occurred_at, a.id) to '__DIR__/5_log_riwayat.csv' with (format csv, header true, encoding 'UTF8')

\copy (select 'Kategori program' as "Jenis", pg_temp.t(name) as "Nama", case when is_active then 'Aktif' else 'Nonaktif' end as "Status", sort_order as "Urutan" from public.program_categories union all select 'Kategori kebutuhan', pg_temp.t(name), case when is_active then 'Aktif' else 'Nonaktif' end, sort_order from public.item_categories union all select 'Divisi', pg_temp.t(d.name) || ' (' || pg_temp.t(g.name) || ')', case when d.is_active then 'Aktif' else 'Nonaktif' end, d.sort_order from public.divisions d join public.division_groups g on g.id = d.group_id order by 1, 4, 2) to '__DIR__/6_master_data.csv' with (format csv, header true, encoding 'UTF8')

-- 7) RAB Gabungan (D-52) - hanya bila tabelnya sudah ada (db/05b_rab_gabungan.sql). Total per baris = total program; "Dihitung" = status Diajukan.
select to_regclass('public.consolidation_members') is not null as ada_rab \gset
\if :ada_rab
\copy (select pg_temp.t(g.name) as "RAB Gabungan", pg_temp.t(g.note) as "Catatan", pg_temp.t(d.name) as "Divisi", pg_temp.t(p.nama_program) as "Nama Program", pg_temp.bulan(p.periode_bulan) as "Bulan", case p.status when 'diajukan' then 'Diajukan' when 'draft' then 'Draft' else '' end as "Status", case when p.id is null then null else coalesce((select sum(i.subtotal) from public.program_items i where i.program_id = p.id), 0) end as "Total (Rp)", case when p.status = 'diajukan' then 'Ya' when p.status = 'draft' then 'Tidak (draft)' else '' end as "Dihitung", p.id as "ID Program", g.id as "ID RAB Gabungan" from public.consolidation_groups g left join public.consolidation_members m on m.group_id = g.id left join public.programs p on p.id = m.program_id left join public.divisions d on d.id = p.division_id order by lower(g.name), g.id, d.sort_order, lower(p.nama_program), p.id) to '__DIR__/7_rab_gabungan.csv' with (format csv, header true, encoding 'UTF8')
\endif
